export function ReputacaoScreen({ ctrl }) {
  const { reputacao, parecerAi, avaliacoes, dadosOp, consistenciaRota, entregasPorDia, topPct, classificacao, analisandoIA, handlePedirAnalise, membroId } = ctrl

  const score = reputacao
  const semAvaliacao = score === 0 && !parecerAi

  const tierLabel = score >= 800 ? 'MASTER TIER' : score >= 700 ? 'GOLD TIER' : score > 0 ? 'STANDARD TIER' : 'SEM SCORE'
  const pct = Math.min(score / 1000, 1)
  const R = 54
  const C = 2 * Math.PI * R
  const dashOffset = C * (1 - pct)

  const trustPct =
    avaliacoes.marcos === 'approved' && avaliacoes.aline === 'approved' ? '100%' :
    avaliacoes.marcos === 'approved' || avaliacoes.aline === 'approved' ? '50%' : '0%'

  const repLogs = [
    { date: '24 MAI', desc: 'Ciclo concluído com evidências', pts: '+25' },
    { date: '18 MAI', desc: 'Aval comunitário registrado', pts: '+15' },
    { date: '10 MAI', desc: 'Orçamento confirmado em oficina', pts: '+10' },
    { date: '02 MAI', desc: 'Membro cadastrado na rede', pts: '+50' },
  ]

  const rec = parecerAi?.recomendacao
  const recColor = rec === 'APROVAR' ? 'var(--success)' : rec === 'ANALISAR' ? 'var(--color-gold)' : rec === 'NEGAR' ? 'var(--color-magenta)' : 'var(--text-secondary)'
  const recBg   = rec === 'APROVAR' ? 'rgba(16,185,129,0.1)' : rec === 'ANALISAR' ? 'rgba(201,154,61,0.1)' : rec === 'NEGAR' ? 'rgba(224,36,124,0.1)' : 'rgba(255,255,255,0.04)'
  const recBorder = rec === 'APROVAR' ? 'rgba(16,185,129,0.3)' : rec === 'ANALISAR' ? 'rgba(201,154,61,0.3)' : rec === 'NEGAR' ? 'rgba(224,36,124,0.3)' : 'var(--border-color)'

  return (
    <div className="screen active" id="screen-reputacao" style={{ paddingBottom: '24px' }}>
      {/* Header */}
      <div style={{ padding: '20px 20px 0' }}>
        <p style={{ fontSize: '0.58rem', color: 'var(--color-magenta)', textTransform: 'uppercase', letterSpacing: '0.14em', fontWeight: 800, marginBottom: '2px' }}>GLOBAL STANDING</p>
        <h3 style={{ fontFamily: 'var(--font-heading)', fontSize: '1.25rem', fontWeight: 900, letterSpacing: '-0.02em' }}>Reputação de Rota</h3>
      </div>

      {/* Circular Score */}
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '24px 20px 16px' }}>
        <div style={{ position: 'relative', width: '140px', height: '140px' }}>
          <svg width="140" height="140" viewBox="0 0 140 140">
            <defs>
              <linearGradient id="goldRing" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#C99A3D" />
                <stop offset="100%" stopColor="#F2C96E" />
              </linearGradient>
            </defs>
            <circle cx="70" cy="70" r={R} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="9" />
            {score > 0 && (
              <circle
                cx="70" cy="70" r={R}
                fill="none"
                stroke="url(#goldRing)"
                strokeWidth="9"
                strokeDasharray={C}
                strokeDashoffset={dashOffset}
                strokeLinecap="round"
                transform="rotate(-90 70 70)"
              />
            )}
          </svg>
          <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%,-50%)', textAlign: 'center' }}>
            {semAvaliacao ? (
              <>
                <i className="fa-solid fa-hourglass-half" style={{ fontSize: '1.4rem', color: 'var(--text-secondary)' }}></i>
                <div style={{ fontSize: '0.48rem', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: 800, marginTop: '4px' }}>AGUARDANDO</div>
              </>
            ) : (
              <>
                <div style={{ fontFamily: 'var(--font-mono)', fontSize: '1.9rem', fontWeight: 700, color: 'var(--text-primary)', lineHeight: 1 }}>{score}</div>
                <div style={{ fontSize: '0.5rem', color: 'var(--color-gold)', textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: 800, marginTop: '2px' }}>{tierLabel}</div>
              </>
            )}
          </div>
        </div>
        {semAvaliacao ? (
          <p style={{ fontSize: '0.63rem', color: 'var(--text-secondary)', textAlign: 'center', marginTop: '8px', lineHeight: 1.4, maxWidth: '220px' }}>
            Nossa IA está avaliando seus dados operacionais.<br />O score será calculado em instantes.
          </p>
        ) : (
          <p style={{ fontSize: '0.63rem', color: 'var(--text-secondary)', textAlign: 'center', marginTop: '8px' }}>
            {topPct != null ? `Top ${topPct}% da rede` : ''}
            {topPct != null && classificacao ? ' • ' : ''}
            {classificacao || ''}
          </p>
        )}
      </div>

      <div style={{ padding: '0 20px', display: 'flex', flexDirection: 'column', gap: '12px' }}>

        {/* Estado: sem dados operacionais */}
        {semAvaliacao && (
          <div style={{ background: 'rgba(201,154,61,0.06)', border: '1px solid rgba(201,154,61,0.2)', borderRadius: '12px', padding: '16px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '10px' }}>
              <i className="fa-solid fa-robot" style={{ color: 'var(--color-gold)', fontSize: '1rem' }}></i>
              <h5 style={{ fontSize: '0.8rem', fontWeight: 800 }}>IA em Análise</h5>
            </div>
            <p style={{ fontSize: '0.7rem', color: 'var(--text-secondary)', lineHeight: 1.45 }}>
              A Abias avalia sua jornada com dados reais: dias ativos, avaliações, rotas concluídas e ganhos efetivos. Nenhum dado de raça ou região entra no cálculo.
            </p>
            <div style={{ marginTop: '12px', display: 'flex', flexDirection: 'column', gap: '6px' }}>
              {[
                ['fa-calendar-check', 'Consistência de dias ativos', '30%'],
                ['fa-wallet',         'Ganho médio semanal',         '25%'],
                ['fa-star',           'Avaliação calibrada por região','20%'],
                ['fa-route',          'Taxa de conclusão de rotas',   '15%'],
                ['fa-handshake',      'Histórico de ciclos Abias',    '10%'],
              ].map(([icon, label, peso]) => (
                <div key={label} style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '0.65rem' }}>
                  <i className={`fa-solid ${icon}`} style={{ color: 'var(--color-gold)', width: '14px', textAlign: 'center', fontSize: '0.7rem' }}></i>
                  <span style={{ flex: 1, color: 'var(--text-secondary)' }}>{label}</span>
                  <span style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, color: 'var(--text-primary)' }}>{peso}</span>
                </div>
              ))}
            </div>
            {membroId && (
              <button
                onClick={handlePedirAnalise}
                disabled={analisandoIA}
                style={{
                  marginTop: '14px', width: '100%', padding: '13px',
                  background: analisandoIA ? 'rgba(201,154,61,0.08)' : 'rgba(201,154,61,0.14)',
                  border: '1px solid rgba(201,154,61,0.4)',
                  borderRadius: '8px',
                  color: analisandoIA ? 'rgba(201,154,61,0.5)' : 'var(--color-gold)',
                  fontSize: '0.75rem', fontWeight: 800, letterSpacing: '0.06em',
                  cursor: analisandoIA ? 'not-allowed' : 'pointer',
                  display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px',
                  transition: 'all 0.2s ease'
                }}
              >
                <i className={`fa-solid ${analisandoIA ? 'fa-spinner fa-spin' : 'fa-brain'}`} style={{ fontSize: '0.8rem' }}></i>
                {analisandoIA ? 'ANALISANDO...' : 'PEDIR ANÁLISE DA IA'}
              </button>
            )}
          </div>
        )}

        {/* Parecer da IA */}
        {parecerAi && (
          <div style={{ background: 'var(--bg-card)', border: `1px solid ${recBorder}`, borderRadius: '12px', overflow: 'hidden' }}>
            <div style={{ padding: '12px 16px', borderBottom: '1px solid var(--border-color)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <i className="fa-solid fa-robot" style={{ color: 'var(--color-gold)', fontSize: '0.8rem' }}></i>
                <h5 style={{ fontSize: '0.65rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.1em' }}>ANÁLISE DA IA</h5>
              </div>
              <span style={{ fontSize: '0.5rem', fontWeight: 800, padding: '3px 8px', background: recBg, border: `1px solid ${recBorder}`, borderRadius: '20px', color: recColor, letterSpacing: '0.06em' }}>
                {rec}
              </span>
            </div>
            <div style={{ padding: '14px 16px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {parecerAi.analise && (
                <p style={{ fontSize: '0.7rem', color: 'var(--text-secondary)', lineHeight: 1.5, fontStyle: 'italic' }}>"{parecerAi.analise}"</p>
              )}
              {parecerAi.fatoresPositivos?.length > 0 && (
                <div>
                  <p style={{ fontSize: '0.55rem', color: 'var(--success)', textTransform: 'uppercase', letterSpacing: '0.08em', fontWeight: 800, marginBottom: '5px' }}>FATORES POSITIVOS</p>
                  {parecerAi.fatoresPositivos.map((f) => (
                    <div key={f} style={{ display: 'flex', alignItems: 'flex-start', gap: '6px', marginBottom: '3px' }}>
                      <i className="fa-solid fa-circle-check" style={{ color: 'var(--success)', fontSize: '0.6rem', marginTop: '2px', flexShrink: 0 }}></i>
                      <span style={{ fontSize: '0.67rem', color: 'var(--text-secondary)', lineHeight: 1.3 }}>{f}</span>
                    </div>
                  ))}
                </div>
              )}
              {parecerAi.pontosAtencao?.length > 0 && (
                <div>
                  <p style={{ fontSize: '0.55rem', color: 'var(--color-gold)', textTransform: 'uppercase', letterSpacing: '0.08em', fontWeight: 800, marginBottom: '5px' }}>PONTOS DE ATENÇÃO</p>
                  {parecerAi.pontosAtencao.map((p) => (
                    <div key={p} style={{ display: 'flex', alignItems: 'flex-start', gap: '6px', marginBottom: '3px' }}>
                      <i className="fa-solid fa-triangle-exclamation" style={{ color: 'var(--color-gold)', fontSize: '0.6rem', marginTop: '2px', flexShrink: 0 }}></i>
                      <span style={{ fontSize: '0.67rem', color: 'var(--text-secondary)', lineHeight: 1.3 }}>{p}</span>
                    </div>
                  ))}
                </div>
              )}
              {parecerAi.consideracaoEquidade && (
                <div style={{ background: 'rgba(224,36,124,0.05)', border: '1px solid rgba(224,36,124,0.15)', borderRadius: '8px', padding: '10px 12px' }}>
                  <p style={{ fontSize: '0.55rem', color: 'var(--color-magenta)', textTransform: 'uppercase', letterSpacing: '0.08em', fontWeight: 800, marginBottom: '4px' }}>VISÃO DE EQUIDADE</p>
                  <p style={{ fontSize: '0.67rem', color: 'var(--text-secondary)', lineHeight: 1.4 }}>{parecerAi.consideracaoEquidade}</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Botão re-análise — visível após primeira avaliação */}
        {!semAvaliacao && membroId && (
          <button
            onClick={handlePedirAnalise}
            disabled={analisandoIA}
            style={{
              width: '100%', padding: '12px',
              background: 'transparent',
              border: '1px solid rgba(201,154,61,0.25)',
              borderRadius: '8px',
              color: analisandoIA ? 'rgba(201,154,61,0.4)' : 'rgba(201,154,61,0.7)',
              fontSize: '0.68rem', fontWeight: 700, letterSpacing: '0.06em',
              cursor: analisandoIA ? 'not-allowed' : 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '7px',
            }}
          >
            <i className={`fa-solid ${analisandoIA ? 'fa-spinner fa-spin' : 'fa-rotate'}`} style={{ fontSize: '0.7rem' }}></i>
            {analisandoIA ? 'REANALISANDO...' : 'SOLICITAR NOVA ANÁLISE DA IA'}
          </button>
        )}

        {/* Community Trust */}
        {score > 0 && (
          <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '12px', padding: '14px', display: 'flex', gap: '12px', alignItems: 'center' }}>
            <div style={{ width: '40px', height: '40px', borderRadius: '50%', background: 'rgba(201,154,61,0.1)', border: '1px solid rgba(201,154,61,0.3)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
              <i className="fa-solid fa-shield-halved" style={{ color: 'var(--color-gold)', fontSize: '1rem' }}></i>
            </div>
            <div style={{ flex: 1 }}>
              <h5 style={{ fontSize: '0.78rem', fontWeight: 800, marginBottom: '2px' }}>Community Trust</h5>
              <p style={{ fontSize: '0.67rem', color: 'var(--text-secondary)', lineHeight: 1.3 }}>
                {trustPct === '100%' ? '2 avais comunitários validados' :
                 trustPct === '50%' ? '1 aval comunitário registrado' :
                 'Nenhum aval registrado ainda'}
              </p>
            </div>
            <span style={{ fontSize: '0.55rem', fontWeight: 800, padding: '3px 8px', background: 'rgba(201,154,61,0.1)', border: '1px solid rgba(201,154,61,0.25)', borderRadius: '20px', color: 'var(--color-gold)', flexShrink: 0 }}>{trustPct}</span>
          </div>
        )}

        {/* Métricas operacionais */}
        {score > 0 && (
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
            <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '12px', padding: '14px' }}>
              <p style={{ fontSize: '0.52rem', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: '6px' }}>Consistência de Rota</p>
              <div style={{ fontFamily: 'var(--font-mono)', fontSize: '1.5rem', fontWeight: 700, color: 'var(--text-primary)', lineHeight: 1 }}>
                {dadosOp ? `${consistenciaRota}%` : '—'}
              </div>
              {dadosOp && (
                <div style={{ height: '3px', background: 'rgba(255,255,255,0.06)', borderRadius: '2px', marginTop: '8px' }}>
                  <div style={{ width: `${consistenciaRota}%`, height: '100%', background: 'var(--color-gold)', borderRadius: '2px' }}></div>
                </div>
              )}
              {dadosOp && <p style={{ fontSize: '0.55rem', color: 'var(--text-secondary)', marginTop: '5px' }}>{dadosOp.diasAtivos} dias ativos / 90</p>}
            </div>
            <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '12px', padding: '14px' }}>
              <p style={{ fontSize: '0.52rem', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: '6px' }}>Avaliação iFood</p>
              <div style={{ fontFamily: 'var(--font-mono)', fontSize: '1.3rem', fontWeight: 700, color: 'var(--success)', lineHeight: 1 }}>
                {dadosOp ? dadosOp.avaliacaoMedia.toFixed(2) : '—'}
              </div>
              {dadosOp && <p style={{ fontSize: '0.55rem', color: 'var(--text-secondary)', marginTop: '5px' }}>{entregasPorDia} entregas/dia • {dadosOp.nivel || 'N/A'}</p>}
            </div>
          </div>
        )}
        {/* Ganhos do período */}
        {score > 0 && dadosOp && (
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
            <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '12px', padding: '14px' }}>
              <p style={{ fontSize: '0.52rem', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: '6px' }}>Ganho Médio Semanal</p>
              <div style={{ fontFamily: 'var(--font-mono)', fontSize: '1rem', fontWeight: 700, color: 'var(--text-primary)', lineHeight: 1 }}>
                {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(dadosOp.ganhoMedioSemanal)}
              </div>
              <p style={{ fontSize: '0.55rem', color: 'var(--text-secondary)', marginTop: '5px' }}>{dadosOp.entregasRealizadas} entregas / 90 dias</p>
            </div>
            <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '12px', padding: '14px' }}>
              <p style={{ fontSize: '0.52rem', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: '6px' }}>Taxa de Conclusão</p>
              <div style={{ fontFamily: 'var(--font-mono)', fontSize: '1rem', fontWeight: 700, color: dadosOp.taxaCancelamento < 0.04 ? 'var(--success)' : 'var(--color-gold)', lineHeight: 1 }}>
                {((1 - dadosOp.taxaCancelamento) * 100).toFixed(1)}%
              </div>
              <p style={{ fontSize: '0.55rem', color: 'var(--text-secondary)', marginTop: '5px' }}>{dadosOp.cancelamentos} cancelamentos no período</p>
            </div>
          </div>
        )}

        {/* Zona de atuação */}
        {score > 0 && (
          <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '12px', padding: '16px', overflow: 'hidden', position: 'relative' }}>
            <div style={{ position: 'absolute', inset: 0, backgroundImage: 'radial-gradient(circle, rgba(201,154,61,0.07) 1px, transparent 1px)', backgroundSize: '18px 18px' }}></div>
            <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%,-50%)', width: '80px', height: '80px', background: 'rgba(201,154,61,0.05)', borderRadius: '50%', filter: 'blur(20px)' }}></div>
            <p style={{ fontSize: '0.52rem', color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.12em', fontWeight: 800, marginBottom: '4px', position: 'relative' }}>RECENTES</p>
            <h5 style={{ fontSize: '0.95rem', fontWeight: 900, letterSpacing: '0.02em', position: 'relative' }}>SÃO PAULO CENTRAL</h5>
            <p style={{ fontSize: '0.63rem', color: 'var(--text-secondary)', marginTop: '4px', position: 'relative' }}>Zona Leste • Zona Centro • Zona Sul</p>
          </div>
        )}

        {/* Rep Logs */}
        {score > 0 && (
          <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border-color)', borderRadius: '12px', overflow: 'hidden' }}>
            <div style={{ padding: '12px 16px', borderBottom: '1px solid var(--border-color)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h5 style={{ fontSize: '0.62rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.12em' }}>REP LOGS</h5>
              <span style={{ fontSize: '0.55rem', color: 'var(--color-gold)', fontWeight: 700, letterSpacing: '0.06em' }}>HISTÓRICO</span>
            </div>
            {repLogs.map(({ date, desc, pts }) => (
              <div key={date} style={{ padding: '10px 16px', borderBottom: '1px solid rgba(255,255,255,0.04)', display: 'flex', alignItems: 'center', gap: '10px' }}>
                <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.58rem', color: 'var(--text-secondary)', flexShrink: 0, width: '44px' }}>{date}</span>
                <span style={{ fontSize: '0.7rem', flex: 1, color: 'var(--text-primary)' }}>{desc}</span>
                <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.75rem', fontWeight: 700, color: 'var(--color-gold)', flexShrink: 0 }}>{pts}</span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}
